// Reference solution
function sortNewest(rows) {
  const idNum = (id) => Number(id.slice(id.indexOf('_') + 1));
  return [...rows]
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt) || idNum(b.id) - idNum(a.id))
    .map((r) => r.id);
}

